import{n as e,t}from"./jsx-runtime-lw2jiZar.js";import{A as n,C as r,H as i,M as a,N as o,O as s,P as c,b as l,k as u,l as d,n as f,o as p,p as m,t as h,v as g}from"./shared-f6Drw7Sx.js";import{t as _}from"./database-LLH4Psoh.js";import{t as v}from"./CodeEditor-BZlrvoTL.js";var y=e(`List`,[[`path`,{d:`M3 12h.01`,key:`nlz23k`}],[`path`,{d:`M3 18h.01`,key:`1tta3j`}],[`path`,{d:`M3 6h.01`,key:`1rqtza`}],[`path`,{d:`M8 12h13`,key:`1za7za`}],[`path`,{d:`M8 18h13`,key:`1lx6n3`}],[`path`,{d:`M8 6h13`,key:`ik3vkj`}]]),b=t(),x=`Глава 4 · Блок 14 · Подготовка базы и новой границы хранения`;function S({module:e}){return(0,b.jsxs)(o,{children:[(0,b.jsx)(a,{variant:`project`,chip:e??x,title:`Чтение через SQL-репо`,intro:`Добавим чтение из SQLite в существующий договор хранения, сохранив обычную Task и рабочий JSON-путь.`,tags:[{icon:(0,b.jsx)(_,{size:14}),label:`SQL и ORM-строки`},{icon:(0,b.jsx)(i,{size:14}),label:`границы слоёв`},{icon:(0,b.jsx)(y,{size:14}),label:`list и get`}]}),(0,b.jsxs)(c,{number:`00`,title:`Один Planner, два способа чтения`,children:[(0,b.jsx)(s,{children:`В предыдущей части пути сервис начал обращаться к предметным операциям хранения, а не разбирать устройство файла в каждом методе. До этого SQL-чтение мы исследовали отдельно; теперь применим его к тем же задачам, сохранив привычную модель Planner.`}),(0,b.jsx)(u,{variant:`connected`,items:[{title:`Точка старта`,description:`Есть предметная Task, PlannerService и полный JSON-путь; в подготовленной части главы появились SQL-таблица, Session и преобразование строки в Task.`},{title:`Новый вопрос`,description:`Как получить тот же список и ту же задачу по id из SQLite, не перенося в репозиторий правила сервиса и HTTP?`},{title:`Результат`,description:`Отдельный SqlTaskRepository читает список и запись, а JSON остаётся штатным путём для API и CLI.`}]}),(0,b.jsx)(`p`,{children:`Пойдём от границы договора к конкретному запросу: сначала определим, кому принадлежит Session, затем разберём получение списка и одной строки, после чего отделим ORM-объект от предметной Task. В конце соберём доказательства на изолированной базе. В истории StudyHub результат занятия 86 отмечен коммитом 3b8498a. Это контрольная точка входа в практику, а не утверждение о том, что любой текущий checkout остановился на ней или на занятии 77. Перед началом сверим нужные файлы.`})]}),(0,b.jsxs)(c,{number:`01`,title:`Операция хранения важнее её внутреннего устройства`,children:[(0,b.jsx)(s,{children:`Сервису нужна задача или список задач. Ему не нужно знать, в каком файле лежит JSON и каким SQL выбирается строка.`}),(0,b.jsx)(`p`,{children:`В прежнем варианте PlannerService просил storage загрузить полный список, а затем находил нужный объект сам. После выделения предметных операций слой хранения получает запрос понятного уровня: вернуть все задачи или найти одну по id. Сервис по-прежнему отвечает за предметные правила, например за то, что неизвестный id превращается в TaskNotFoundError. Репозиторий отвечает за получение данных и возвращает знакомые Task.`}),(0,b.jsx)(n,{rows:[[(0,b.jsx)(`code`,{children:`JSON-репозиторий`}),`Читает текущий снимок через существующий JsonStorage и превращает записи в предметные задачи.`],[(0,b.jsx)(`code`,{children:`SQL-репозиторий`}),`Выполняет запрос через переданную Session и превращает ORM-строки в те же предметные задачи.`]]}),(0,b.jsx)(`p`,{children:`Это похоже на переходник для одной розетки: прибор получает привычное питание, хотя форма разъёма у источника может быть другой. Здесь «прибором» является вызывающий код, ожидающий list или get, а переходниками являются две реализации хранения. Граница аналогии важна: репозитории не обязаны иметь одинаковый набор внутренних действий, но каждая готовая операция должна соблюдать один и тот же предметный результат.`}),(0,b.jsx)(`p`,{children:`Поэтому новый класс не становится вторым PlannerService и не принимает HTTP-схемы. Он не решает, какой статус вернуть, как сортировать пользовательский запрос с фильтрами или что делать при ошибке сервиса. Сейчас договор ограничен чтением списка и одной записи. Методы записи, поиск, статистика и фильтры появятся отдельно; пока считать их готовыми нельзя.`}),(0,b.jsx)(`p`,{children:`Репозиторий относится к границе хранения, а не к HTTP-слою. В проекте app/routers/tasks собраны router.py и схемы запросов и ответов. Если поместить туда SQL-доступ, расположение будет подсказывать неверную зависимость: будто база является частью маршрута. Поэтому SqlTaskRepository находится в app/DBase/repositories.py рядом с engine, Session и ORM-моделью. Существующий app/repositories.py при этом содержит JSON-адаптер. PlannerService зависит от общего договора, а HTTP-маршрут вызывает сервис и не знает, какой адаптер тот использует.`})]}),(0,b.jsxs)(c,{number:`02`,title:`Session приходит извне и возвращается владельцу`,children:[(0,b.jsx)(s,{children:`Session даёт коду рабочий доступ к базе в рамках одной операции. Создать её, передать и закрыть должны части программы, которые организуют эту ресурсную область.`}),(0,b.jsx)(`p`,{children:`Engine и фабрика Session переиспользуются как настроенная инфраструктура, а сама Session создаётся для отдельной работы. Вызывающая сторона открывает её и передаёт в SqlTaskRepository. Репозиторий пользуется сессией, но не владеет ею. После чтения вызывающая сторона завершает область и закрывает ресурс, даже если запрос завершился ошибкой.`}),(0,b.jsx)(`p`,{children:`Можно представить читальный зал библиотеки. Посетитель получает место и право работать с каталогом на время визита; библиотекарь у стойки помогает найти запись, но не закрывает зал вместо посетителя. Здесь фабрика выдаёт Session, репозиторий выполняет чтение, а код-владелец освобождает ресурс. Граница аналогии: Session не является интерфейсной страницей или постоянной базой, это объект для взаимодействия с ней.`}),(0,b.jsx)(h,{caption:`Путь данных для чтения списка`,orientation:`horizontal`,children:(0,b.jsxs)(p,{label:`SQL-строка превращается в предметную задачу`,orientation:`horizontal`,children:[(0,b.jsx)(d,{title:`Запрос Session`,shape:`input-output`,children:(0,b.jsx)(`p`,{children:`select(TaskRow) с явным порядком`})}),(0,b.jsx)(f,{label:`получает ORM-строки`}),(0,b.jsx)(d,{title:`TaskRow`,shape:`database`,children:(0,b.jsx)(`p`,{children:`Поля таблицы tasks`})}),(0,b.jsx)(f,{label:`task_from_row`}),(0,b.jsx)(d,{title:`Task`,shape:`process`,children:(0,b.jsx)(`p`,{children:`Обычные объекты Planner`})})]})}),(0,b.jsx)(`p`,{children:`На схеме мы читаем слева направо: запрос на Session возвращает ORM-объекты, преобразование копирует нужные значения, а вызывающий код получает предметные Task. Сама Session проходит рядом как переданный ресурс и остаётся у владельца. Репозиторий не закрывает её и не вызывает commit: при чтении он не обещает записать изменение.`}),(0,b.jsx)(l,{question:`Кто закрывает Session после вызова SqlTaskRepository.list()?`,options:[`Код, который создал Session и передал её репозиторию.`,`Репозиторий, чтобы не оставить подключение открытым.`,`TaskRow после преобразования в Task.`],correctIndex:0,explanation:`Мы передали репозиторию заёмный ресурс. Его жизненным циклом управляет создавшая его область, поэтому один репозиторий не закрывает Session, которую могут использовать другие шаги этой операции.`})]}),(0,b.jsxs)(c,{number:`03`,title:`Список требует явного порядка`,children:[(0,b.jsx)(s,{children:`Для набора записей одного вызова Session недостаточно: запрос, результат SQLAlchemy и предметный список являются разными этапами.`}),(0,b.jsx)(`p`,{children:`В независимом примере библиотечного каталога select(NoteRow) описывает, какие ORM-записи мы хотим получить. Вызов session.scalars выполняет выражение и возвращает последовательность отдельных NoteRow, а all собирает их в список. Ни select, ни scalars сами не создают предметные объекты Note. Это похоже на заявку в архив: формулировка запроса ещё не стопка найденных карточек, а полученные карточки ещё не краткие заметки, которые мы передадим дальше.`}),(0,b.jsx)(g,{code:`statement = select(NoteRow).order_by(NoteRow.id)
rows = session.scalars(statement).all()
notes = [Note(row.id, row.title) for row in rows]`,steps:[{line:0,note:`Мы описываем выборку и просим базу вернуть записи по id. Явный порядок важен: без order_by база не обещает расположение строк.`,vars:{statement:`выборка NoteRow, порядок по id`}},{line:1,note:`Session выполняет запрос, scalars оставляет ORM-объекты, а all собирает результат. Если строк нет, rows равен пустому списку.`,vars:{rows:`[NoteRow(id=2), NoteRow(id=8)]`}},{line:2,note:`Мы создаём отдельные предметные Note из полей ORM-строк. Здесь список уже содержит Note, а не объекты SQLAlchemy.`,vars:{notes:`[Note(2, ...), Note(8, ...)]`}}]}),(0,b.jsx)(`p`,{children:`Пустая таблица естественно даёт пустой список. Несколько строк дают несколько элементов, и если дальнейшая проверка сравнивает их порядок, порядок следует задать внутри SQL через order_by. Нельзя полагаться на то, как строки случайно лежали в файле базы или были возвращены в одном запуске.`}),(0,b.jsx)(`p`,{children:`В нашем репозитории список задач упорядочивается по id и отображается тем же преобразованием task_from_row, которое уже связывает TaskRow с Task. На этом уровне не добавляем is_done, limit, статистику или поиск: они изменили бы предметный договор и относятся к следующим SQL-операциям.`})]}),(0,b.jsxs)(c,{number:`04`,title:`Чтение по id возвращает запись или отсутствие`,children:[(0,b.jsx)(s,{children:`Запрос одной строки отвечает на другой вопрос, поэтому его результат нужно отличать от списка.`}),(0,b.jsx)(`p`,{children:`Session.get(TaskRow, task_id) ищет объект по первичному ключу. Если строка существует, мы получаем ORM-объект. Если такого id нет, результат равен None. Список и единичное чтение не следует сводить к одной форме: пустой список значит, что подходящих строк списка нет, а None значит, что конкретная запрошенная запись отсутствует.`}),(0,b.jsx)(`p`,{children:`SqlTaskRepository возвращает None без исключения и без придуманной пустой Task. Проверка предметного id и перевод отсутствия в TaskNotFoundError принадлежат PlannerService. HTTP-слой уже решает, что это означает для ответа, например прежний статус 404. Поэтому app/DBase/repositories.py не импортирует FastAPI, HTTPException или схемы запросов.`}),(0,b.jsx)(m,{prompt:`Соединим форму результата с запросом, который её создаёт.`,leftTitle:`Запрос`,rightTitle:`Результат`,pairs:[{left:`list при пустой таблице`,right:`пустой список`},{left:`get с существующим id`,right:`предметная Task после mapping`},{left:`get с неизвестным id`,right:`None для решения в сервисе`},{left:`сбой запроса`,right:`ошибка проходит к вызывающему коду`}],explanation:`Мы сохраняем различие между отсутствующим набором, отсутствующей строкой и ошибкой выполнения. Repository не превращает эти случаи в один и не выдаёт HTTP-ответ.`})]}),(0,b.jsxs)(c,{number:`05`,title:`Возвращаем Task, а не ORM-строку`,children:[(0,b.jsx)(s,{children:`Операция чтения должна выдать понятный предметному коду результат, который не зависит от последующей работы ORM.`}),(0,b.jsx)(`p`,{children:`TaskRow описывает строку таблицы и связан с SQLAlchemy. Task описывает предметную задачу и уже используется сервисом, JSON и CLI. Похожие поля не делают их взаимозаменяемыми. Функция task_from_row проводит явное преобразование в одном направлении: база знает, как создать Task, но модель Task не должна импортировать SQLAlchemy.`}),(0,b.jsx)(`p`,{children:`Преобразование переносит id, title, priority, is_done и tags. Служебный title_normalized остаётся частью хранения для будущего поиска и не появляется в Task или HTTP-схеме. Для tags создаётся отдельный список: изменение полученной Task не должно менять список в ORM-строке или у другой задачи.`}),(0,b.jsx)(`p`,{children:`Аналогия с переводчиком помогает увидеть направление. Переводчик читает карточку в одном формате и выдаёт обычное сообщение на языке получателя; он не заставляет получателя импортировать правила каталога. Но аналогия ограничена: mapping не переводит смысл задачи заново, а аккуратно переносит её уже известные поля.`}),(0,b.jsx)(v,{caption:`Фрагмент независимого преобразования карточки каталога`,code:`def note_from_row(row):
    return Note(
        id=row.id,
        title=row.title,
        labels=list(row.labels),
    )`}),(0,b.jsx)(`p`,{children:`Явное преобразование важно и для срока жизни результата. Session остаётся ресурсом владельца, а ORM-строки принадлежат модели хранения. Возвращённая Task содержит обычные значения, поэтому её поля можно использовать после завершения области Session без нового ленивого обращения к базе. Мы не утверждаем, что каждое чтение ORM-атрибута непременно сломается после close; мы убираем эту зависимость из договора репозитория.`}),(0,b.jsx)(r,{code:`def get(self, task_id):
    row = self.session.get(TaskRow, task_id)
    self.session.close()
    return row`,question:`Какая граница нарушена в этом методе?`,options:[`Репозиторий закрывает переданную Session и возвращает ORM-строку вместо Task.`,`Метод возвращает None для существующей строки.`,`Метод сортирует одну строку по id.`],correctIndex:0,explanation:`Мы не владеем Session, потому что получили её извне, и не должны закрывать её. Кроме того, результат ещё связан с ORM-моделью. Преобразуем найденную запись и оставляем закрытие владельцу.`,fix:`def get(self, task_id):
    row = self.session.get(TaskRow, task_id)
    if row is None:
        return None
    return task_from_row(row)`})]}),(0,b.jsxs)(c,{number:`06`,title:`Проверяем две операции и предел их возможностей`,children:[(0,b.jsx)(s,{children:`Набор проверок должен доказывать реальный SQL-путь и одновременно удерживать его узким.`}),(0,b.jsx)(`p`,{children:`Для проверки создаём отдельную файловую SQLite-базу во временной папке, строим в ней исходную схему и добавляем заранее известные строки. Отдельный файл защищает рабочий JSON и базу приложения. Мы не подменяем Session воображаемым объектом: настоящая SQLite-проверка подтверждает, что выражение выполнилось, ORM-строки получены и mapping создал ожидаемую Task.`}),(0,b.jsx)(`p`,{children:`Сначала проверяем пустую таблицу, затем несколько записей с разными id, статусами и tags. Список должен быть упорядочен, а каждая Task должна содержать пять предметных полей. Отдельно запрашиваем существующий и неизвестный id. Результат используем после выхода из области Session; затем повторно читаем сохранённые строки в другой сессии, чтобы подтвердить, что чтение не изменило данные.`}),(0,b.jsx)(`p`,{children:`У репозитория чтения нет причины вызывать commit: он не объявляет изменений. Ему также не нужно закрывать Session за вызывающий код. Проверка может подтвердить эти границы по коду и наблюдаемому результату. Для пустого списка и неизвестного id мы не возвращаем фиктивные объекты, а одинаковые ожидаемые предметные результаты сравниваем с JSON-реализацией.`}),(0,b.jsx)(`p`,{children:`Здесь особенно важно не принять частичную реализацию за готовую замену. У SqlTaskRepository появились только list и get. Если подключить его как единственный backend сейчас, PlannerService может запросить создание, изменение, поиск или статистику, которых в классе нет. Скрытый переход на JSON при таких вызовах тоже неверен: он создаст две незаметно расходящиеся дороги. Поэтому обычные API, CLI и build_service продолжают использовать полный JSON-путь.`}),(0,b.jsx)(`p`,{children:`Успешный SQL-тест не переключает продукт и не доказывает, что все операции уже работают. Он показывает более узкий результат: две операции чтения соблюдают знакомый предметный контракт и готовы к следующей проверке GET по id. В следующем занятии ресурс Session подключится к существующему HTTP-пути. Запись, фильтры, поиск и статистика появятся по мере того, как их SQL-реализации будут готовы.`})]}),(0,b.jsxs)(c,{number:`07`,title:`Что мы будем делать в практике`,children:[(0,b.jsx)(s,{children:`Теперь мы добавим только два SQL-чтения в существующий Planner и подтвердим, что остальная программа остаётся на JSON.`}),(0,b.jsx)(u,{variant:`connected`,items:[{title:`Подтвердим исходную точку`,description:`Коммит 3b8498a отмечает результат занятия 86. Для более нового checkout сверим фабрику сессий, схему, TaskRow → Task и полный JSON-адаптер.`},{title:`Добавим list и get`,description:`В app/DBase/repositories.py создадим SqlTaskRepository. Он получает Session извне и возвращает Task или None; модуль маршрута останется HTTP-слоем.`},{title:`Проверим SQLite`,description:`На отдельной файловой fixture подтвердим пустой и упорядоченный список, известный и неизвестный id, tags и результат после закрытия Session.`},{title:`Сохраним рабочий путь`,description:`Оставим штатную сборку API и CLI на полном JSON-репозитории и прогоним существующие проверки без участия рабочих данных.`}]}),(0,b.jsx)(`p`,{children:`Каждый шаг опирается на одну и ту же границу: Session выдаёт владелец, SQL-репозиторий отвечает за чтение, task_from_row возвращает предметную модель, а сервис решает предметную ошибку. Известная контрольная точка после занятия 86 зафиксирована коммитом 3b8498a. В своей копии сверим app/DBase/session.py, app/DBase/models.py, app/repositories.py и app/services.py: там должны быть make_session_factory, исходная схема и mapping, полный JSON-адаптер и сервис поверх репозитория. Более новый HEAD допустим, если эта основа сохранена. Повторять занятия 78–86 не нужно, когда их результат уже присутствует.`}),(0,b.jsx)(`p`,{children:`После работы у нас будут проверенные list/get, но не новый API и не переключение на базу. Следующее занятие сможет подключить одну из этих операций к существующему GET и проверить ресурсную область. Мы сохраняем JSON, CLI, API-контракт и все остальные операции без изменений.`})]})]})}export{S as Lesson87};